previewCss:
.darma-loader-darma-b7-hourglass-flip { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #78350f); width: var(--loader-size, 72px); height: var(--loader-size, 72px); position: relative; animation: darma-loader-darma-b7-hourglass-flip-hourglass calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.68, 0, .32, 1) infinite; }
.darma-loader-darma-b7-hourglass-flip::before, .darma-loader-darma-b7-hourglass-flip::after { content: ''; position: absolute; left: 0; width: 0; height: 0; border-left: calc(var(--loader-size, 72px) / 2) solid transparent; border-right: calc(var(--loader-size, 72px) / 2) solid transparent; }
.darma-loader-darma-b7-hourglass-flip::before { top: 0; border-top: calc(var(--loader-size, 72px) / 2) solid var(--accent); }
.darma-loader-darma-b7-hourglass-flip::after { bottom: 0; border-bottom: calc(var(--loader-size, 72px) / 2) solid var(--accent-2); }
@keyframes darma-loader-darma-b7-hourglass-flip-hourglass { 0%, 35% { transform: rotate(0deg); } 50%, 85% { transform: rotate(180deg); } 100% { transform: rotate(360deg); } }

